from concurrent.futures import ThreadPoolExecutor, as_completed
import socket

def scan_port(host, port, timeout=0.5):
    s = socket.socket()
    s.settimeout(timeout)
    code = s.connect_ex((host, port))
    s.close()
    if code == 0:
        return port, 'open'
    return port, 'closed'

def scan_ports(host, ports, timeout=0.5, max_threads=100):
    open_ports = []
    with ThreadPoolExecutor(max_workers=max_threads) as executor:
        future_to_port = {executor.submit(scan_port, host, p, timeout): p for p in ports}
        for future in as_completed(future_to_port):
            port, status = future.result()
            if status == 'open':
                open_ports.append(port)
    return open_ports

import socket
from concurrent.futures import ThreadPoolExecutor, as_completed

def resolve_host(host):
    try:
        return socket.gethostbyname(host)
    except socket.gaierror:
        return None

def check_port(host, port, timeout):
    s = socket.socket()
    s.settimeout(timeout)
    code = s.connect_ex((host, port))
    s.close()
    return (port, code == 0)

def scan_ports(target, start_port, end_port, timeout=0.5, threads=100):
    ip = resolve_host(target)
    if not ip:
        print(f"Could not resolve {target}")
        return []
    ports = range(start_port, end_port+1)
    open_ports = []
    with ThreadPoolExecutor(max_workers=threads) as ex:
        futures = {ex.submit(check_port, ip, p, timeout): p for p in ports}
        for future in as_completed(futures):
            port, is_open = future.result()
            if is_open:
                open_ports.append(port)
    return sorted(open_ports)
